// Pure asynchronous preparation, synchronous exact-phase draw. No timer/RAF/clock ownership.
const sha=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),v=>v.toString(16).padStart(2,'0')).join('');
export async function prepareLosslessWater({layout,read,inflate,signal}){
 let closed=false,task=null,wanted=null,completedMs=null;const rows=[];const freeze=o=>{for(const v of Object.values(o))if(v&&typeof v==='object')freeze(v);return Object.freeze(o)};const check=()=>{if(closed||signal?.aborted)throw Error('WETLAND_WATER_CLOSED')};
 const dispose=()=>{if(closed)return;closed=true;wanted=null;for(const r of rows){r.bundle=null;r.ids=null;r.rgb=null;r.cache?.clear();r.phase=-1;r.pinnedPhase=null}rows.length=0};
 const privateLayout=freeze(structuredClone(layout));try{check();if(privateLayout.format!=='WETLAND_ORIGINAL_RGB_XOR_PREVIOUS_ZLIB_KEY12_V1'||privateLayout.rows.length!==5)throw Error('WATER_LAYOUT');for(const external of privateLayout.rows){const r=freeze(structuredClone(external));const bundle=new Uint8Array(await read(r.bundlePath)),rawIds=new Uint8Array(await read(r.indicesPath));check();if(bundle.length!==r.bundleBytes||await sha(bundle)!==r.bundleSHA||rawIds.length!==r.indicesBytes||await sha(rawIds)!==r.indicesSHA)throw Error('WATER_LAYOUT_PIN');const ids=new Uint32Array(rawIds.buffer.slice(rawIds.byteOffset,rawIds.byteOffset+rawIds.byteLength));if(ids.length!==r.pixels||r.frameRecords.length!==r.frames)throw Error('WATER_LAYOUT_LENGTH');rows.push({spec:r,bundle,ids,phase:-1,pinnedPhase:null,rgb:null,cache:new Map()});}check();
 const phase=(r,ms)=>Math.floor((((ms%14400)+14400)%14400)/(r.spec.periodMs/r.spec.frames))%r.spec.frames;
 async function prepare(ms){check();if(!Number.isFinite(ms))throw Error('WATER_CLOCK');for(const r of rows){const target=phase(r,ms);if(r.cache.has(target))continue;let start=target-target%12,previous=null;if(r.phase>=start&&r.phase<target){start=r.phase+1;previous=r.rgb}for(let i=start;i<=target;i++){check();const f=r.spec.frameRecords[i],decoded=new Uint8Array(await inflate(r.bundle.subarray(f.offset,f.offset+f.bytes)));check();if(decoded.length!==r.spec.pixels*3)throw Error('WATER_FRAME_LENGTH');if(!f.key){if(!previous)throw Error('WATER_KEY');for(let j=0;j<decoded.length;j++)decoded[j]^=previous[j]}if(await sha(decoded)!==f.decodedSHA)throw Error('WATER_FRAME_PIN');check();previous=decoded}check();r.rgb=previous;r.phase=target;r.cache.set(target,previous);while(r.cache.size>2){const drop=[...r.cache.keys()].find(k=>k!==r.pinnedPhase&&k!==target);if(drop===undefined)throw Error('WATER_CACHE_BOUND');r.cache.delete(drop)}}check();completedMs=ms;}
 return Object.freeze({pin(ms){check();if(!Number.isFinite(ms)||rows.some(r=>!r.cache.has(phase(r,ms))))throw Error('WATER_PIN_NOT_PREPARED');for(const r of rows)r.pinnedPhase=phase(r,ms);},isPrepared(ms){check();return Number.isFinite(ms)&&rows.every(r=>r.cache.has(phase(r,ms)))},advance(ms){check();if(!Number.isFinite(ms))return Promise.reject(Error('WATER_CLOCK'));wanted=ms;if(task)return task;task=(async()=>{try{while(wanted!==null){const next=wanted;wanted=null;await prepare(next)}return Object.freeze({preparedMs:completedMs})}finally{task=null}})();return task},draw(rgba,camera,ms){check();if(!(rgba instanceof Uint8ClampedArray)||camera.length!==4||!camera.every(Number.isInteger)||!Number.isFinite(ms))throw Error('WATER_DRAW');const[cx,cy,w,h]=camera;if(cx<0||cy<0||cx+w>2836||cy+h>1820||w<1||h<1||rgba.length!==w*h*4)throw Error('WATER_CAMERA');if(rows.some(r=>!r.cache.has(phase(r,ms))))throw Error('WATER_PHASE_NOT_PREPARED');const written={};for(const r of rows){const rgb=r.cache.get(phase(r,ms));written[r.spec.name]=0;for(let i=0;i<r.ids.length;i++){const id=r.ids[i],x=id%2836-cx,y=Math.floor(id/2836)-cy;if(x<0||x>=w||y<0||y>=h)continue;const d=(y*w+x)*4,s=i*3;rgba[d]=rgb[s];rgba[d+1]=rgb[s+1];rgba[d+2]=rgb[s+2];written[r.spec.name]++}}return written},memory(){check();return{entries:rows.map(r=>({name:r.spec.name,phase:r.phase,pinnedPhase:r.pinnedPhase,compressedBytes:r.bundle.length,indicesBytes:r.ids.byteLength,currentRGBBytes:r.rgb?.length??0,cachedPhases:[...r.cache].map(([phase,rgb])=>({phase,bytes:rgb.length}))})),maxOneOwnerFrameBytes:Math.max(...rows.map(r=>r.spec.pixels*3)),compressedBytes:rows.reduce((n,r)=>n+r.bundle.length,0),indicesBytes:rows.reduce((n,r)=>n+r.ids.byteLength,0),activeFrameBytes:rows.reduce((n,r)=>n+(r.rgb?.length??0),0),cachedPhaseBytes:rows.reduce((n,r)=>n+[...r.cache.values()].reduce((s,b)=>s+b.length,0),0),maxCachedPhasesPerOwner:2,activeFrames:rows.filter(r=>r.rgb).length,inFlight:task!==null,pendingRequests:wanted===null?0:1}},dispose});
 }catch(e){dispose();throw e}
}
